<script setup lang="ts">
import{computed,ref}from'vue';import{onLoad}from'@dcloudio/uni-app';import AppHeader from'../../components/AppHeader.vue';import StatusNotice from'../../components/StatusNotice.vue';import{api,apiRuntime}from'../../api/client';import{toOrderProjection,type ProjectProjection}from'../../api/project-contract';import{fromProjection}from'../../domain/price-snapshot';import{validateOrderSnapshot}from'../../domain/snapshot-flow';import{getOrCreateCommand}from'../../domain/command-identity';import type{OrderProjection}from'../../domain/types'
const p=ref<OrderProjection|null>(null),core=ref<ProjectProjection|null>(null),orderRef=ref(''),error=ref(''),loading=ref(false);const ready=computed(()=>validateOrderSnapshot(uni,orderRef.value,p.value?fromProjection(p.value):null));const canConfirmPayment=computed(()=>ready.value&&!!core.value?.allowedActions.some(a=>a.actionCode==='REQUEST_MOCK_PAYMENT'))
async function refresh(){if(!orderRef.value)return;error.value='';try{if(apiRuntime.mode==='PROJECT_MOCK_API'){core.value=await api.getCoreProjection(orderRef.value);p.value=toOrderProjection(core.value)}else p.value=await api.getProjection(orderRef.value)}catch{error.value='暂时无法确认付款结果，请稍后查询。'}}
async function confirmPayment(){if(!canConfirmPayment.value||!core.value)return;loading.value=true;try{const c=getOrCreateCommand(uni,`mock-payment:${orderRef.value}`);core.value=await api.confirmMockPayment(orderRef.value,c.commandId,c.idempotencyKey,core.value.projectionVersion,core.value.aggregateVersion);uni.navigateTo({url:`/pages/order/progress?orderRef=${encodeURIComponent(orderRef.value)}`})}catch{error.value='付款结果暂时无法确认，请勿重复支付。'}finally{loading.value=false}}
onLoad(q=>{orderRef.value=typeof q?.orderRef==='string'?decodeURIComponent(q.orderRef):'';refresh()})
</script>
<template><view class="page"><AppHeader left="返回" @left="uni.navigateBack()"/><view class="content"><text class="step">第 3 步，共 3 步</text><view class="heading" role="heading" aria-level="1">确认付款结果</view><text class="desc">请保持页面打开，我们正在确认本次付款。</text><StatusNotice v-if="error" tone="unknown" title="付款结果暂时无法确认">{{error}}</StatusNotice><StatusNotice v-if="p&&!ready" tone="risk" title="订单信息已更新">请返回订单重新核对，当前不会继续处理。</StatusNotice><view class="card"><text class="card-title">请勿重复支付</text><text class="copy">网络较慢时，关闭页面后也可以从“我的订单”继续查询。</text></view></view><view class="action"><button v-if="apiRuntime.mode==='PROJECT_MOCK_API'" class="primary" :disabled="!canConfirmPayment||loading" @click="confirmPayment">{{loading?'正在确认…':'继续确认付款'}}</button><button v-else class="primary" @click="refresh">查询付款结果</button></view></view></template><style src="../../styles/shared.css"></style>
